#!/bin/bash# 招投标每日追踪 — 数据管线（intel 分身的数据来源）# 用法: run_daily.sh [YYYY-MM-DD]# 流程: 4平台抓取 → 聚合 → 聚合文本+当日JSON 落 input/09_情报_intel/招投标每日/{日期}/# 日报生成由 Claude（intel 分身）负责：桌面 App 定时任务或手动 /招投标日报set -u# 自定位：按脚本自身位置推导仓库根（与 run_reports.sh 同款，兼容任意目录调起）SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"REPO="$(cd "$SELF_DIR/../.." && pwd)"SCRIPTS="$REPO/tools/bidding-intel/scripts"PY="/usr/bin/python3"DATE="${1:-$(date +%Y-%m-%d)}"INPUT="$REPO/input/09_情报_intel/招投标每日/$DATE"LOG="$SCRIPTS/logs/run_daily_$DATE.log"mkdir -p "$INPUT" "$SCRIPTS/logs"cd "$SCRIPTS" || exit 1echo "===== run_daily $DATE 开始 $(date '+%H:%M:%S') =====" >> "$LOG"# 0) 乐采云依赖 Chrome 调试端口 9222——不在就拉起（独立 profile，不影响日常使用的 Chrome）if ! curl -s -m 3 http://127.0.0.1:9222/json/version >/dev/null 2>&1; then  echo "[INFO] 9222 未响应，拉起 Chrome 调试实例" >> "$LOG"  "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" \    --remote-debugging-port=9222 --no-proxy-server \    --user-data-dir="$HOME/.openclaw/chrome-debug-profile" >> "$LOG" 2>&1 &  sleep 8fi# 1) 四平台抓取（单平台失败不阻断其余平台；乐采云依赖 Chrome 调试端口 9222）for s in zjgov_daily tzgg_daily lecaiyun_daily tzygcg_daily; do  echo "----- $s -----" >> "$LOG"  "$PY" "$s.py" "$DATE" >> "$LOG" 2>&1 || echo "[WARN] $s 失败，跳过（详见上方日志）" >> "$LOG"done# 2) 四平台聚合 → 推送文本落 input；信息流 JSON（四类分组，工作台行业情报页读）落 outputsTRACK="$REPO/outputs/03_招投标_bidding/招投标每日追踪"mkdir -p "$TRACK""$PY" daily_aggregate.py "$DATE" --feed-json "$TRACK/${DATE}_信息流.json" > "$INPUT/${DATE}_四平台聚合.md" 2>> "$LOG" \  || echo "[WARN] daily_aggregate 失败" >> "$LOG"# 3) 当日原始 JSON 一并归档到 input（无当日文件属正常：当天无新增）cp -f "$SCRIPTS"/*_data_"$DATE".json "$INPUT/" 2>/dev/nullecho "===== run_daily $DATE 结束 $(date '+%H:%M:%S') =====" >> "$LOG"echo "OK: $INPUT"